SELECT d.location, CASE WHEN d.dept_name IN ('Sales', 'Marketing') THEN 'core' ELSE 'other' END AS dept_name_group, SUM(e.salary) AS total_salary, MAX(e.salary) - MIN(e.salary) AS salary_range FROM employees e INNER JOIN departments d ON e.dept_id = d.id WHERE d.budget >= 1567000 GROUP BY d.location, CASE WHEN d.dept_name IN ('Sales', 'Marketing') THEN 'core' ELSE 'other' END ORDER BY salary_range
